with gaps as (select *, case when lag(paid_at) over (partition by order_id order by paid_at, id) is null or paid_at > lag(paid_at) over (partition by order_id order by paid_at, id) + interval 60 days then 1 else 0 end as is_new_session from payments), sessionized as (select id, order_id, amount, paid_at, status, sum(is_new_session) over (partition by order_id order by paid_at, id rows between unbounded preceding and current row) as session_id from gaps) select date_trunc('quarter', paid_at) as quarter_start, order_id, avg(amount) filter (where status = 'REFUNDED') as refunded_avg_amount, round(sum(amount) / nullif(count(case when status = 'REFUNDED' then 1 end), 0), 2) as amount_per_refunded, approx_percentile(amount, 0.95) as amount_p95, count(distinct id) as distinct_ids, round(avg(amount), 2) as avg_amount, rank() over (partition by date_trunc('quarter', paid_at) order by round(sum(amount) / nullif(count(case when status = 'REFUNDED' then 1 end), 0), 2) desc) as amount_per_refunded_rank from sessionized group by 1, 2
